import {depthHtml} from './course-depth.mjs';
import React from 'react';
import {renderToStaticMarkup} from 'react-dom/server';
import * as Lucide from 'lucide-react';
import {family,courseIds,courseIcons,ventureSteps,names,primary,titles} from './data.mjs';
import {marketing,courseScreens,courseGate,brochureRoutes} from './marketing.mjs';
