function graph(list=false){return `<svg class="graph" viewBox="0 0 650 285" role="img" aria-label="${list?'Linked list pointer diagram':'Graph traversal diagram with nodes A through F'}">${list?`<path d="M145 140h50m95 0h50m95 0h50" fill="none" stroke="#8c7cdb" stroke-width="3"/>${[90,240,390,540].map((x,i)=>`<g class="graph-node ${i===0?'current':''}" data-node="${i}"><rect x="${x-45}" y="112" width="90" height="56" rx="8"/><text x="${x}" y="145" text-anchor="middle">${[12,24,36,48][i]}</text><text x="${x}" y="200" text-anchor="middle">${i===3?'null':'next'}</text></g>`).join('')}`:`${[[100,140,270,65],[100,140,270,220],[270,65,450,65],[270,65,450,220],[270,220,450,220],[450,65,570,140],[450,220,570,140]].map(([x1,y1,x2,y2])=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/>`).join('')}${[[100,140],[270,65],[270,220],[450,65],[450,220],[570,140]].map(([x,y],i)=>`<g class="graph-node ${i===0?'current':''}" data-node="${i}"><circle cx="${x}" cy="${y}" r="26"/><text x="${x}" y="${y+5}" text-anchor="middle">${'ABCDEF'[i]}</text></g>`).join('')}`}</svg>`;}

